type Version struct { Effective time.Time; Terms Terms }   // immutable snapshot by value
type Contract struct { ID string; versions []Version }     // continuity, ascending
func (c *Contract) AsOf(on time.Time) (Terms, bool) {
    i := sort.Search(len(c.versions), func(i int) bool { return c.versions[i].Effective.After(on) })
    if i == 0 { return Terms{}, false }                    // Missing Version
    return c.versions[i-1].Terms, true
}
func (c *Contract) Amend(effective time.Time, terms Terms) {
    i := sort.Search(len(c.versions), func(i int) bool { return !c.versions[i].Effective.Before(effective) })
    c.versions = slices.Insert(c.versions, i, Version{Effective: effective, Terms: terms})
}
